using System;
using System.IO;
using System.Collections.Generic;
using Molinos.Scato.Dominio.Comandos;
using Molinos.Scato.Dominio.Dto;
using Molinos.Scato.Dominio.Entidades;
using Molinos.Scato.Repositorio;
using Molinos.Scato.Servicios;
using Molinos.Scato.Servicios.Conversiones;
using Molinos.Scato.Servicios.Orquestador;
using Molinos.Scato.Servicios.Procesamiento;
using Molinos.Scato.Test.Mock;
using Moq;
using NUnit.Framework;

namespace Molinos.Scato.Test.Procesamiento
{
    [TestFixture]
    public class ProcesadorAgregarMarcaSustentableTest
    {
        private ProcesadorAgregarMarcaSustentable target;
        private Mock<IRepositorio> repositorioMock;
        private Mock<IConversor> conversorMock;
        private Mock<IConfiguracionProvider> configuracionMock;

        private string imageBase64;

        [SetUp]
        public void SetUp()
        {
            repositorioMock = new Mock<IRepositorio>();
            conversorMock = new Mock<IConversor>();
            configuracionMock = new Mock<IConfiguracionProvider>();
            target = new ProcesadorAgregarMarcaSustentable(repositorioMock.Object, conversorMock.Object, new NullLogger(), configuracionMock.Object);

            imageBase64 = "";
        }

        [Test]
        public void TestAgregarSello()
        {            
            var comando = new AgregarMarcaSustentable
            {
                RutaFotoCP = null,
                CodigoCentroSap = null,
                NroDocumento = null,
                SoloDibujar = true,
                PdfImage = Convert.FromBase64String(imageBase64)
            };
            var resultado = target.Ejecutar(comando) as ResultadoCartaPorteElectronica;
            Assert.That(resultado, Is.Not.Null);
            Assert.That(resultado.HayErrores, Is.EqualTo(false));
            Assert.AreNotEqual(Convert.ToBase64String(resultado.PdfImageSustentable), imageBase64);
        }
    }
}
